"""Publish Wikipedia-derived historical catalog separately from the Egyptian factual compilation."""
import pathlib,json,html,urllib.parse,shutil
ROOT=pathlib.Path(__file__).resolve().parents[2]
data=json.loads((ROOT/'src/data/lowerLeagues.json').read_text()); egypt=json.loads((ROOT/'src/data/egyptPyramid.json').read_text()); esc=html.escape
(ROOT/'public/data/lower-leagues.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
shutil.copyfile(ROOT/'src/data/egyptPyramid.json',ROOT/'public/data/egypt-pyramid.json')
rows=[]
for l in data:
 title=urllib.parse.quote(l['wiki'].replace(' ','_'));url='https://en.wikipedia.org/w/index.php?title='+title+('&oldid='+str(l['revision']) if l.get('revision') else '');history='https://en.wikipedia.org/w/index.php?title='+title+'&action=history'
 rows.append(f'<tr><td>{esc(l["name"])}'+(' — تاريخي؛ ليس بداية مصر الجديدة' if l['country']=='eg' else '')+f'</td><td>{len(l["clubs"])}</td><td><a href="{esc(url)}">Article</a> · <a href="{esc(history)}">Contributors</a></td></tr>')
sources=''.join(f'<li><a href="{esc(s["url"])}">{esc(s["url"])}</a> · {esc(s["date"])} · {esc(s["use"])}</li>' for s in egypt['sources'])
text='''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مصادر الدرجات الأقل — 0.6</title><style>body{font:17px/1.9 system-ui;background:#14251f;color:#e8efe9;padding:24px;max-width:1000px;margin:auto}a{color:#c1ed96}td,th{padding:14px;border-bottom:1px solid #415748}table{width:100%;font-size:14px;overflow-wrap:anywhere}.scroll{overflow:auto}li{overflow-wrap:anywhere}</style><a href="/">العودة للعبة</a><h1>مصادر أندية الدرجات الأقل</h1><h2>مصر — تجميع حقائق منشورة، مراجعة 25 سبتمبر 2026</h2><p>الثانية أ: 20 ناديًا. الثانية ب: 11 + 10 + 17 + 16 + 16 = 70 اسمًا في خمس مجموعات قابلة للعب. لا مستوى رابع مستنتج، ولا هبوط إليه. هذه أسماء أندية حقيقية مع لاعبين مولّدين، وليست شهادة قيد رسمي لموسم 2026/27.</p><p>اختلاف المصادر مهم: تقرير أغسطس يقول 69 بينما قائمته تضم 68، وقائمة القاهرة فيه لا تطابق تقارير المباريات اللاحقة. وُفّقت عضوية القاهرة من قائمة 17 اسمًا وتقارير سبتمبر وعودة أورانج. دلتا يونايتد مذكور باعتباره بلقاس سيتي سابقًا؛ لا نجزم بتطابقه مع الاسم القديم ميجا سبورت الوارد في سطر جدول المصدر. مفاتيح الأندية الإنجليزية معرفات تقنية وليست أسماء رسمية معتمدة.</p><p>هذا تجميع مستقل لحقائق الأسماء والمجموعات، وليس نقلًا لنصوص الأخبار أو الصور أو الشعارات أو جداول نتائجها. المواقع الصحفية ليست قواعد لاعبين مفتوحة المصدر، ولا ندّعي ترخيص مقالاتها بترخيص ويكيبيديا. الروابط أدناه للإسناد والمراجعة.</p><ul>'''+sources+'''</ul><p><a href="/data/egypt-pyramid.json" download>التجميع المصري مع المراجع والقيود JSON</a></p><h2>نظام الصعود في المحاكاة</h2><p>أول اثنين من كل مجموعة صعيد إلى ملحق أربعة فرق ذهابًا وإيابًا؛ يصعد الأول. أول اثنين من كل مجموعة القاهرة والقناة وبحري إلى ملحق ستة فرق من دور واحد؛ يصعد الأول والثاني. المواعيد محاكاة وليست الجدول الحقيقي. التعادل يبدأ بالمواجهات المباشرة ثم فارق الأهداف؛ التساوي الكامل يحسم بالهوية الثابتة بدل المباراة الفاصلة. الملاحق لا تنقل إنذارات لأن نظام الانضباط التفصيلي لم يُنفّذ. يتم توزيع الهابطين في المقاعد الشاغرة للمحافظة على الأحجام؛ ليس توزيعًا جغرافيًا رسميًا.</p><h2>ويكيبيديا — باقي الدرجات وكتالوج العضوية الأقدم</h2><p>اقتباس أسماء الأندية من ويكيبيديا ومساهمي المقالات بترخيص <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>، والقاعدة المكيّفة بنفس الترخيص. التغيير: اختيار الجداول، تعيين المعرفات والدرجات، واستبعاد التكرار مع الدرجة الأولى. بعض المصادر قديمة ولا تضمن قيد 2026/27. سجل مصر القديم محفوظ للتوافق مع الحفظات السابقة، ولا يُستخدم لبدء مشوار جديد.</p><p>الإجمالي الحالي 19 مسابقة أقل في 9 بلدان، مع 50 مسابقة عليا؛ ليس هرمًا مكتملًا لكل بلد. قدرات اللاعبين والمنشآت والميزانيات والاقتصاد تقديرات محاكاة مستقلة.</p><p><a href="/data/lower-leagues.json" download>بيانات ويكيبيديا والكتالوج التاريخي JSON</a> · <a href="/data-license.html">مصادر اللاعبين الحقيقيين</a></p><div class="scroll"><table><tr><th>المسابقة</th><th>الأسماء بالمصدر قبل إزالة التكرار</th><th>المصدر والمساهمون</th></tr>'''+''.join(rows)+'''</table></div><p dir="ltr">Wikipedia-derived catalog: CC BY-SA 4.0, changes: extraction, ID/country/tier mapping, duplicate filtering. Revision IDs were not available for the lower-tier discovery; these links are not pinned snapshots. Egyptian membership: separate original factual compilation with attribution, not republished news prose and not certified current registration. No federation endorsement.</p></html>'''
(ROOT/'public/lower-data-license.html').write_text(text)
print('Published 13 non-Egypt lower definitions + 6 Egyptian definitions; retained historical Wikipedia catalog.')
